//! Rust code emitter: `enums.rs`, one module per domain, and a `mod.rs` barrel.

use std::collections::BTreeSet;
use std::fmt::Write as _;

use crate::schema::{Domain, FieldType, Schema, TypeDef, TypeHome};

const DERIVES: &str = "#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]";

fn header(schema: &Schema) -> String {
    format!(
        "//! Generated by corpora-typegen from the schema v{}.\n\
         //! Do not edit by hand; regenerate with `cargo run -p corpora-typegen`.\n",
        schema.version
    )
}

/// Render the schema as `(file name, content)` pairs: `mod.rs`, `enums.rs`
/// and one `<domain>.rs` per domain.
pub fn emit(schema: &Schema) -> Vec<(String, String)> {
    let mut files = vec![
        ("mod.rs".to_owned(), emit_barrel(schema)),
        ("enums.rs".to_owned(), emit_enums(schema)),
    ];
    for (domain_name, domain) in &schema.domains {
        files.push((
            format!("{domain_name}.rs"),
            emit_domain(schema, domain_name, domain),
        ));
    }
    files
}

fn emit_barrel(schema: &Schema) -> String {
    let mut out = header(schema);
    let _ = writeln!(out);
    let _ = writeln!(out, "pub mod enums;");
    for domain_name in schema.domains.keys() {
        let _ = writeln!(out, "pub mod {domain_name};");
    }
    let _ = writeln!(out);
    let _ = writeln!(out, "pub use enums::*;");
    for domain_name in schema.domains.keys() {
        let _ = writeln!(out, "pub use {domain_name}::*;");
    }
    out
}

fn emit_enums(schema: &Schema) -> String {
    let mut out = header(schema);
    let _ = writeln!(out);
    for (name, def) in &schema.enums {
        let _ = writeln!(out, "/// {}", def.description);
        let _ = writeln!(out, "{DERIVES}");
        let _ = writeln!(out, "pub enum {name} {{");
        for value in &def.values {
            let _ = writeln!(out, "    /// `{value}`");
            let _ = writeln!(out, "    #[serde(rename = \"{value}\")]");
            let _ = writeln!(out, "    {},", variant_name(value));
        }
        let _ = writeln!(out, "}}\n");
    }
    out
}

fn emit_domain(schema: &Schema, domain_name: &str, domain: &Domain) -> String {
    let mut out = header(schema);
    let _ = writeln!(
        out,
        "//!\n//! Domain `{domain_name}`: {}",
        domain.description
    );
    let _ = writeln!(out);

    for import in imports(schema, domain_name, domain) {
        let _ = writeln!(out, "{import}");
    }
    let _ = writeln!(out);

    for (union_name, union) in &schema.unions {
        if schema.type_home(union_name) == Some(TypeHome::Union(domain_name)) {
            let _ = writeln!(out, "/// {}", union.description);
            let _ = writeln!(out, "{DERIVES}");
            let _ = writeln!(out, "#[serde(tag = \"type\", rename_all = \"snake_case\")]");
            let _ = writeln!(out, "pub enum {union_name} {{");
            for variant in &union.variants {
                let _ = writeln!(out, "    /// A `{variant}` node.");
                let _ = writeln!(out, "    {variant}({variant}),");
            }
            let _ = writeln!(out, "}}\n");
        }
    }

    for (type_name, type_def) in &domain.types {
        emit_struct(&mut out, schema, type_name, type_def);
    }
    out
}

/// `use super::...` lines for types this domain references but does not declare.
fn imports(schema: &Schema, domain_name: &str, domain: &Domain) -> Vec<String> {
    let mut lines = BTreeSet::new();
    for type_def in domain.types.values() {
        for (_, field) in type_def.fields() {
            for named in FieldType::parse(&field.ty).named() {
                match schema.type_home(named) {
                    Some(TypeHome::Enum) => {
                        lines.insert(format!("use super::enums::{named};"));
                    }
                    Some(TypeHome::Struct(home) | TypeHome::Union(home)) if home != domain_name => {
                        lines.insert(format!("use super::{home}::{named};"));
                    }
                    _ => {}
                }
            }
        }
    }
    lines.into_iter().collect()
}

fn emit_struct(out: &mut String, schema: &Schema, name: &str, def: &TypeDef) {
    let _ = writeln!(out, "/// {}", def.description);
    let _ = writeln!(out, "{DERIVES}");
    let _ = writeln!(out, "pub struct {name} {{");
    if let Some(parent) = def.extends.as_deref() {
        if let Some((_, parent_def)) = schema.find_type(parent) {
            emit_fields(out, schema, parent_def);
        }
    }
    emit_fields(out, schema, def);
    let _ = writeln!(out, "}}\n");
}

fn emit_fields(out: &mut String, schema: &Schema, def: &TypeDef) {
    for (field_name, field) in def.fields() {
        let _ = writeln!(out, "    /// {}", field.description);
        let rust_name = escape_keyword(field_name);
        let wire_name = field.wire_name.as_deref().unwrap_or(field_name);
        if field.omit_if_none {
            let _ = writeln!(
                out,
                "    #[serde(skip_serializing_if = \"Option::is_none\")]"
            );
        }
        if rust_name != wire_name {
            let _ = writeln!(out, "    #[serde(rename = \"{wire_name}\")]");
        }
        let ty = rust_type(schema, &FieldType::parse(&field.ty));
        let _ = writeln!(out, "    pub {rust_name}: {ty},");
    }
}

fn rust_type(schema: &Schema, ty: &FieldType) -> String {
    match ty {
        FieldType::Named(name) => schema
            .scalars
            .get(name)
            .map_or_else(|| name.clone(), |scalar| scalar.rust.clone()),
        FieldType::Optional(inner) => format!("Option<{}>", rust_type(schema, inner)),
        FieldType::List(inner) => format!("Vec<{}>", rust_type(schema, inner)),
        FieldType::Map(key, value) => format!(
            "std::collections::BTreeMap<{}, {}>",
            rust_type(schema, key),
            rust_type(schema, value)
        ),
    }
}

/// `ready-for-review` -> `ReadyForReview`, `tf_zip` -> `TfZip`, `not reviewed` -> `NotReviewed`.
fn variant_name(value: &str) -> String {
    value
        .split(['-', '_', ' '])
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            chars.next().map_or_else(String::new, |first| {
                first.to_uppercase().collect::<String>() + chars.as_str()
            })
        })
        .collect()
}

fn escape_keyword(name: &str) -> String {
    match name {
        "type" | "ref" | "use" | "move" | "box" => format!("r#{name}"),
        _ => name.to_owned(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn variant_name_should_pascal_case_kebab_values() {
        assert_eq!(variant_name("ready-for-review"), "ReadyForReview");
    }

    #[test]
    fn variant_name_should_pascal_case_spaced_values() {
        assert_eq!(variant_name("not reviewed"), "NotReviewed");
    }

    #[test]
    fn escape_keyword_should_rawify_type() {
        assert_eq!(escape_keyword("type"), "r#type");
    }
}
